const REVISION_UNITS = [{"id": "acids_bases", "name": "Acids, Bases & Acid Reactions", "source": "Y10_Acids_Bases_Unit_Plan_2026.docx", "status": "ready", "skills": [{"id": "acids_bases-ph", "name": "pH and classification", "summary": "Acids have pH below 7; neutral solutions have pH 7; alkaline solutions have pH above 7. pH does not identify a chemical or prove it is safe.", "blanks": ["below", "7", "above"], "questions": [{"prompt": "Classify a solution with pH 3: acidic, neutral or alkaline?", "answer": "acidic", "aliases": ["acid"], "explanation": "pH below 7 is acidic.", "cloze": "A solution with pH 3 is ____."}, {"prompt": "Classify a solution with pH 11.", "answer": "alkaline", "aliases": ["alkali", "basic"], "explanation": "pH above 7 is alkaline.", "cloze": "A solution with pH 11 is ____."}, {"prompt": "A liquid has pH 7. Does that prove it is safe to drink? Answer yes or no.", "answer": "no", "aliases": [], "explanation": "Neutral pH does not rule out harmful dissolved substances.", "cloze": "A liquid with pH 7 is proven safe to drink: ____ (yes/no)."}]}, {"id": "acids_bases-base", "name": "Bases and alkalis", "summary": "A base neutralises an acid. An alkali is a base that dissolves in water. Not all bases are alkalis.", "blanks": ["neutralises", "dissolves"], "questions": [{"prompt": "What name is given to a base that dissolves in water?", "answer": "alkali", "aliases": ["an alkali"], "explanation": "Soluble bases are alkalis.", "cloze": "A base that dissolves in water is an ____."}, {"prompt": "Copper oxide is an insoluble base. Is it an alkali?", "answer": "no", "aliases": [], "explanation": "It neutralises acids but does not dissolve in water.", "cloze": "Copper oxide is an insoluble base. It is an alkali: ____ (yes/no)."}, {"prompt": "Sodium hydroxide dissolves in water. Is it a base, an alkali, or both?", "answer": "both", "aliases": [], "explanation": "An alkali is a type of base.", "cloze": "Sodium hydroxide dissolves in water. It is ____ (a base/an alkali/both)."}]}, {"id": "acids_bases-indicators", "name": "Indicators", "summary": "Acids turn blue litmus red; alkalis turn red litmus blue. Universal indicator estimates pH using a colour chart; neutral is green.", "blanks": ["red", "blue", "green"], "questions": [{"prompt": "An acid turns blue litmus what colour?", "answer": "red", "aliases": [], "explanation": "Blue litmus turns red in an acid.", "cloze": "An acid turns blue litmus ____."}, {"prompt": "An alkali turns red litmus what colour?", "answer": "blue", "aliases": [], "explanation": "Red litmus turns blue in an alkali.", "cloze": "An alkali turns red litmus ____."}, {"prompt": "Which indicator is better for estimating pH: litmus or universal indicator?", "answer": "universal indicator", "aliases": [], "explanation": "Compare its colour with a pH colour chart; litmus only classifies acid/base.", "cloze": "For estimating pH, the better indicator is ____."}]}, {"id": "acids_bases-neutralisation", "name": "Neutralisation", "summary": "Acid + base → salt + water. Adding base to an acid raises its pH towards neutral; excess base can make the solution alkaline.", "blanks": ["salt", "water", "raises"], "questions": [{"prompt": "Acid + base makes salt and what other product?", "answer": "water", "aliases": [], "explanation": "This is the neutralisation pattern.", "cloze": "Acid + base → salt + ____."}, {"prompt": "Does adding base to an acidic solution initially raise or lower pH?", "answer": "rise", "aliases": ["increase", "raise"], "explanation": "The solution becomes less acidic.", "cloze": "Adding base to an acidic solution initially causes its pH to ____."}, {"prompt": "If excess alkali is added after neutralisation, is the final solution acidic, neutral or alkaline?", "answer": "alkaline", "aliases": [], "explanation": "Adding too much alkali takes the pH above 7.", "cloze": "After excess alkali is added, the solution is ____."}]}, {"id": "acids_bases-salts", "name": "Naming salts", "summary": "Hydrochloric acid forms chlorides; sulfuric acid forms sulfates; nitric acid forms nitrates. The metal supplies the first part of the salt name.", "blanks": ["chlorides", "sulfates", "nitrates"], "questions": [{"prompt": "Magnesium reacts with hydrochloric acid. Name the salt.", "answer": "magnesium chloride", "aliases": [], "explanation": "Magnesium supplies the first name; hydrochloric acid supplies chloride.", "cloze": "Magnesium + hydrochloric acid → ____ + hydrogen."}, {"prompt": "Zinc oxide reacts with sulfuric acid. Name the salt.", "answer": "zinc sulfate", "aliases": ["zinc sulphate"], "explanation": "Zinc supplies the first name; sulfuric acid supplies sulfate.", "cloze": "Zinc oxide + sulfuric acid → ____ + water."}, {"prompt": "Calcium carbonate reacts with nitric acid. Name the salt.", "answer": "calcium nitrate", "aliases": [], "explanation": "Calcium supplies the first name; nitric acid supplies nitrate.", "cloze": "Calcium carbonate + nitric acid → ____ + water + carbon dioxide."}]}, {"id": "acids_bases-metal", "name": "Acids and metals", "summary": "Acid + reactive metal → salt + hydrogen. Bubbles are evidence of gas production; they do not identify the gas. A lit splint gives hydrogen a squeaky pop.", "blanks": ["hydrogen", "lit", "pop"], "questions": [{"prompt": "A reactive metal and an acid produce which gas?", "answer": "hydrogen", "aliases": [], "explanation": "Acid + reactive metal → salt + hydrogen.", "cloze": "Reactive metal + acid → salt + ____."}, {"prompt": "Which gas gives a squeaky pop with a lit splint?", "answer": "hydrogen", "aliases": [], "explanation": "The hydrogen pop test identifies this gas.", "cloze": "The gas that gives a squeaky pop with a lit splint is ____."}, {"prompt": "Magnesium + hydrochloric acid produces magnesium chloride and which gas?", "answer": "hydrogen", "aliases": [], "explanation": "This follows the acid + metal pattern.", "cloze": "Magnesium + hydrochloric acid → magnesium chloride + ____."}]}, {"id": "acids_bases-carbonate", "name": "Acids and carbonates", "summary": "Acid + metal carbonate → salt + water + carbon dioxide. Carbon dioxide turns limewater cloudy.", "blanks": ["water", "carbon dioxide", "cloudy"], "questions": [{"prompt": "Which gas forms when an acid reacts with a metal carbonate?", "answer": "carbon dioxide", "aliases": ["CO2", "CO₂"], "explanation": "Carbonates release carbon dioxide when reacting with acids.", "cloze": "Acid + metal carbonate → salt + water + ____."}, {"prompt": "What happens to limewater when carbon dioxide is bubbled through it?", "answer": "turns cloudy", "aliases": ["cloudy", "milky", "turns milky"], "explanation": "The cloudiness is the positive gas-test observation.", "cloze": "With carbon dioxide bubbled through it, limewater ____."}, {"prompt": "Acid + carbonate → salt + carbon dioxide + which often-forgotten product?", "answer": "water", "aliases": [], "explanation": "The carbonate pattern has three products.", "cloze": "Acid + carbonate → salt + carbon dioxide + ____."}]}, {"id": "acids_bases-word", "name": "Word equations and evidence", "summary": "Reactants go before the arrow; products go after it. Word equations name substances. A chemical reaction forms new substances.", "blanks": ["Reactants", "products", "new substances"], "questions": [{"prompt": "In magnesium + hydrochloric acid → magnesium chloride + hydrogen, name the metal reactant.", "answer": "magnesium", "aliases": [], "explanation": "Reactants are before the arrow.", "cloze": "In magnesium + hydrochloric acid → magnesium chloride + hydrogen, the metal reactant is ____."}, {"prompt": "In hydrochloric acid + sodium hydroxide → sodium chloride + water, name the salt product.", "answer": "sodium chloride", "aliases": [], "explanation": "Products are after the arrow; sodium chloride is the salt.", "cloze": "In hydrochloric acid + sodium hydroxide → sodium chloride + water, the salt product is ____."}, {"prompt": "Bubbles appear during an acid reaction. Do bubbles alone identify hydrogen: yes or no?", "answer": "no", "aliases": [], "explanation": "Use the gas test; bubbles alone only indicate gas production.", "cloze": "Bubbles alone identify hydrogen: ____ (yes/no)."}]}, {"id": "acids_bases-balance", "name": "Scaffolded symbol equations", "summary": "Balance equations by changing coefficients, never subscripts. The number of atoms of each element is equal on both sides. Use provided formulas.", "blanks": ["coefficients", "subscripts", "equal"], "questions": [{"prompt": "Balance Mg + __ HCl → MgCl2 + H2. Give the missing coefficient.", "answer": "2", "aliases": [], "explanation": "Two HCl provide two chlorine atoms and two hydrogen atoms.", "cloze": "Mg + ____ HCl → MgCl2 + H2."}, {"prompt": "Balance CaCO3 + __ HCl → CaCl2 + H2O + CO2. Give the missing coefficient.", "answer": "2", "aliases": [], "explanation": "Ca: 1, C: 1, O: 3, H: 2 and Cl: 2 on each side.", "cloze": "CaCO3 + ____ HCl → CaCl2 + H2O + CO2."}, {"prompt": "Balance H2SO4 + __ NaOH → Na2SO4 + 2 H2O. Give the missing coefficient.", "answer": "2", "aliases": [], "explanation": "Two NaOH give two sodium atoms; all other atom totals also match.", "cloze": "H2SO4 + ____ NaOH → Na2SO4 + 2 H2O."}]}, {"id": "acids_bases-applications", "name": "Applying reaction patterns", "summary": "Antacids neutralise excess stomach acid. Acid reacting with limestone produces carbon dioxide. Observation and explanation are different.", "blanks": ["neutralise", "carbon dioxide"], "questions": [{"prompt": "Antacid is a base. Which reaction reduces excess stomach acidity?", "answer": "neutralisation", "aliases": ["neutralization"], "explanation": "Acid + base produces salt + water.", "cloze": "Antacids reduce excess stomach acidity by ____."}, {"prompt": "Limestone contains calcium carbonate. Which gas forms when it reacts with acid rain?", "answer": "carbon dioxide", "aliases": ["CO2", "CO₂"], "explanation": "Use the acid + carbonate pattern.", "cloze": "Limestone reacting with acid rain releases ____."}, {"prompt": "Is “bubbles appeared” an observation or an explanation?", "answer": "observation", "aliases": [], "explanation": "It states what was seen rather than why it happened.", "cloze": "“Bubbles appeared” is an ____ (observation/explanation)."}]}], "applications": [{"prompt": "A student says all bubbles from acid reactions are hydrogen. Compare acid + magnesium with acid + calcium carbonate. State the products and the gas test for each.", "answer": "Acid + magnesium → salt + hydrogen; a lit splint gives a squeaky pop. Acid + calcium carbonate → salt + water + carbon dioxide; carbon dioxide turns limewater cloudy. Bubbles do not distinguish the gases."}, {"prompt": "Hydrochloric acid reacts with calcium hydroxide. Write a word equation, then balance Ca(OH)2 + HCl → CaCl2 + H2O. Explain why changing a subscript would be wrong.", "answer": "Hydrochloric acid + calcium hydroxide → calcium chloride + water. Ca(OH)2 + 2 HCl → CaCl2 + 2 H2O. Coefficients change particle counts; subscripts change substance identity."}, {"prompt": "A solution changes from pH 2 to pH 8 as alkali is added. Explain the change and why the final pH does not prove that the solution is safe to drink.", "answer": "Adding alkali neutralises acid and raises pH; excess alkali makes it alkaline. pH does not identify every dissolved substance or establish safety."}]}, {"id": "atomic_matter", "name": "Atomic Science / Matter", "source": "Y10_Atomic Science Unit Plan 2026.docx", "status": "ready", "skills": [{"id": "atomic_matter-changes", "name": "Physical and chemical changes", "summary": "A physical change forms no new substance. A chemical change forms new substances by rearranging particles; reversibility alone is not the definition.", "blanks": ["no new substance", "new substances"], "questions": [{"prompt": "Is ice melting a physical or chemical change?", "answer": "physical", "aliases": ["physical change"], "explanation": "It remains water; no new substance forms.", "cloze": "Ice melting is a ____ change."}, {"prompt": "Is magnesium burning a physical or chemical change?", "answer": "chemical", "aliases": ["chemical change"], "explanation": "Magnesium oxide is a new substance.", "cloze": "Magnesium burning is a ____ change."}, {"prompt": "Wax melts and then burns. Which part is physical: melting or burning?", "answer": "melting", "aliases": [], "explanation": "Melting changes state; burning creates new substances.", "cloze": "Wax melts and burns. The physical change is ____."}]}, {"id": "atomic_matter-states", "name": "States and state changes", "summary": "Solid particles vibrate about fixed positions; liquid particles move past each other; gas particles are far apart. Condensation changes gas to liquid.", "blanks": ["fixed", "past", "gas to liquid"], "questions": [{"prompt": "What is the name for liquid changing to gas?", "answer": "evaporation", "aliases": ["vaporisation", "vaporization"], "explanation": "Particles escape from the liquid; boiling is also liquid to gas.", "cloze": "Liquid → gas is called ____."}, {"prompt": "What is the name for gas changing to liquid?", "answer": "condensation", "aliases": [], "explanation": "Particles come closer together to form a liquid.", "cloze": "Gas → liquid is called ____."}, {"prompt": "Which state has particles vibrating about fixed positions?", "answer": "solid", "aliases": [], "explanation": "Particles move but remain around fixed positions.", "cloze": "Particles vibrating about fixed positions are in a ____."}]}, {"id": "atomic_matter-particles", "name": "Subatomic particles", "summary": "Protons are positive, neutrons neutral and electrons negative. Protons and neutrons are in the nucleus; electrons occupy shells outside it.", "blanks": ["positive", "neutral", "negative", "nucleus"], "questions": [{"prompt": "Which subatomic particle has a negative charge?", "answer": "electron", "aliases": ["electrons"], "explanation": "Electrons occupy shells outside the nucleus.", "cloze": "The negatively charged subatomic particle is the ____."}, {"prompt": "Which subatomic particle has no charge?", "answer": "neutron", "aliases": ["neutrons"], "explanation": "Neutrons are neutral and lie in the nucleus.", "cloze": "The uncharged subatomic particle is the ____."}, {"prompt": "Which positively charged particles determine an element’s identity?", "answer": "protons", "aliases": ["proton"], "explanation": "The number of protons is the atomic number.", "cloze": "The positively charged particles that determine an element’s identity are ____."}]}, {"id": "atomic_matter-counts", "name": "Atomic and mass numbers", "summary": "Atomic number = protons. Mass number = protons + neutrons. A neutral atom has equal numbers of protons and electrons.", "blanks": ["protons", "neutrons", "equal"], "questions": [{"prompt": "A neutral atom has atomic number 11. How many electrons does it have?", "answer": "11", "aliases": [], "explanation": "Neutral atoms have electrons = protons = atomic number.", "cloze": "A neutral atom with atomic number 11 has ____ electrons."}, {"prompt": "An atom has mass number 23 and atomic number 11. How many neutrons?", "answer": "12", "aliases": [], "explanation": "Neutrons = 23 − 11 = 12.", "cloze": "An atom with mass number 23 and atomic number 11 has ____ neutrons."}, {"prompt": "An atom has 8 protons and 10 neutrons. What is its mass number?", "answer": "18", "aliases": [], "explanation": "Mass number = 8 + 10. Do not use rounded relative atomic mass as isotope data.", "cloze": "An atom with 8 protons and 10 neutrons has mass number ____."}]}, {"id": "atomic_matter-shells", "name": "Electron arrangements", "summary": "For the first 20 neutral atoms, use the school shell model 2,8,8,2. Valence electrons occupy the outermost shell.", "blanks": ["20", "outermost"], "questions": [{"prompt": "Give the electron arrangement of neutral sodium, atomic number 11.", "answer": "2,8,1", "aliases": ["2 8 1", "2-8-1"], "explanation": "Fill 2 in the first shell, 8 in the second, then 1.", "cloze": "Neutral sodium (atomic number 11) has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral calcium, atomic number 20.", "answer": "2,8,8,2", "aliases": ["2 8 8 2", "2-8-8-2"], "explanation": "This is the school shell model for the first 20 elements.", "cloze": "Neutral calcium (atomic number 20) has electron arrangement ____."}, {"prompt": "An atom has electron arrangement 2,8,7. How many valence electrons?", "answer": "7", "aliases": [], "explanation": "Count electrons in the outermost shell.", "cloze": "An atom with arrangement 2,8,7 has ____ valence electrons."}]}, {"id": "atomic_matter-table", "name": "Groups, periods and trends", "summary": "Groups are vertical columns; periods are horizontal rows. Reactivity increases down groups 1 and 2 but decreases down group 17. Group 18 is very unreactive.", "blanks": ["vertical", "horizontal", "increases", "decreases"], "questions": [{"prompt": "Are groups vertical columns or horizontal rows?", "answer": "vertical columns", "aliases": ["vertical", "columns"], "explanation": "Periods are the horizontal rows.", "cloze": "Groups in the periodic table are ____."}, {"prompt": "Does group 1 reactivity increase or decrease down the group?", "answer": "increase", "aliases": ["increases"], "explanation": "Group 1 metals become more reactive down the group.", "cloze": "Down group 1, reactivity tends to ____."}, {"prompt": "Does group 17 reactivity increase or decrease down the group?", "answer": "decrease", "aliases": ["decreases"], "explanation": "Halogens become less reactive down the group.", "cloze": "Down group 17, reactivity tends to ____."}]}, {"id": "atomic_matter-metals", "name": "Metals and non-metals", "summary": "Metals usually conduct heat and electricity, are shiny, malleable and ductile. Properties have exceptions; mercury is a liquid metal at room temperature.", "blanks": ["conduct", "malleable", "ductile"], "questions": [{"prompt": "What word means a metal can be hammered into shape?", "answer": "malleable", "aliases": [], "explanation": "Malleable means shaped by hammering.", "cloze": "A metal that can be hammered into shape is ____."}, {"prompt": "What word means a metal can be drawn into wires?", "answer": "ductile", "aliases": [], "explanation": "Ductile metals can be pulled into wires.", "cloze": "A metal that can be drawn into wires is ____."}, {"prompt": "Is mercury at room temperature a solid, liquid or gas?", "answer": "liquid", "aliases": [], "explanation": "Mercury is an exception to the usual solid state of metals.", "cloze": "At room temperature, mercury is a ____."}]}, {"id": "atomic_matter-ions", "name": "Ions and electron transfer", "summary": "Ions form by gaining or losing electrons. Losing electrons makes a positive cation; gaining electrons makes a negative anion. Proton count stays the same.", "blanks": ["electrons", "positive", "negative"], "questions": [{"prompt": "A neutral sodium atom loses one electron. Give its ion charge.", "answer": "+1", "aliases": ["1+", "+"], "explanation": "It has one more proton than electron.", "cloze": "A neutral sodium atom loses one electron. Its ion charge is ____."}, {"prompt": "A chlorine atom gains one electron. Give its ion charge.", "answer": "-1", "aliases": ["1-", "−1", "-"], "explanation": "It has one more electron than proton.", "cloze": "A neutral chlorine atom gains one electron. Its ion charge is ____."}, {"prompt": "When an atom becomes an ion, does its proton count change: yes or no?", "answer": "no", "aliases": [], "explanation": "Only its electron count changes in ion formation.", "cloze": "When an atom becomes an ion, its proton count changes: ____ (yes/no)."}]}, {"id": "atomic_matter-formula", "name": "Ionic formulas", "summary": "Ionic compounds have zero overall charge. Balance positive and negative ion charges to choose the smallest whole-number ratio.", "blanks": ["zero", "smallest"], "questions": [{"prompt": "Given Mg2+ and Cl−, write the formula of magnesium chloride.", "answer": "MgCl2", "aliases": ["MgCl₂"], "explanation": "One +2 ion needs two −1 ions.", "cloze": "Mg2+ and Cl− combine to form ____."}, {"prompt": "Given Na+ and O2−, write the formula of sodium oxide.", "answer": "Na2O", "aliases": ["Na₂O"], "explanation": "Two +1 ions balance one −2 ion.", "cloze": "Na+ and O2− combine to form ____."}, {"prompt": "Given Ca2+ and NO3−, write calcium nitrate’s formula.", "answer": "Ca(NO3)2", "aliases": ["Ca(NO₃)₂"], "explanation": "Two whole nitrate ions are needed; brackets keep the ion together.", "cloze": "Ca2+ and NO3− combine to form ____."}, {"prompt": "Given Na+ and Cl−, name NaCl.", "answer": "sodium chloride", "explanation": "The metal name comes first; chlorine becomes chloride.", "aliases": [], "cloze": "NaCl is named ____."}, {"prompt": "Given Mg2+ and O2−, write magnesium oxide’s formula.", "answer": "MgO", "explanation": "A 1:1 ratio balances +2 and −2.", "aliases": [], "cloze": "Mg2+ and O2− combine to form ____."}, {"prompt": "Given Ca2+ and OH−, write calcium hydroxide’s formula.", "answer": "Ca(OH)2", "explanation": "Two hydroxide ions balance one calcium ion.", "aliases": [], "cloze": "Ca2+ and OH− combine to form ____."}]}, {"id": "atomic_matter-ions2", "name": "Common ion names", "summary": "Oxide is O2−, chloride Cl−, fluoride F− and sulfide S2−. Hydroxide is OH−, carbonate CO3²−, sulfate SO4²− and nitrate NO3−.", "blanks": ["Oxide", "Hydroxide", "carbonate", "nitrate"], "questions": [{"prompt": "Name the ion OH−.", "answer": "hydroxide", "aliases": [], "explanation": "Hydroxide is a polyatomic ion with overall charge −1.", "cloze": "OH− is the ____ ion."}, {"prompt": "Name the ion CO3²−.", "answer": "carbonate", "aliases": [], "explanation": "Carbonate is a polyatomic ion with overall charge −2.", "cloze": "CO3²− is the ____ ion."}, {"prompt": "Name the ion SO4²−.", "answer": "sulfate", "aliases": ["sulphate"], "explanation": "Sulfate has overall charge −2.", "cloze": "SO4²− is the ____ ion."}]}, {"id": "atomic_matter-symbols0", "name": "Element symbols 1–6", "summary": "hydrogen = H; helium = He; lithium = Li; beryllium = Be; boron = B; carbon = C.", "blanks": ["H", "He", "Li", "Be", "B", "C"], "questions": [{"prompt": "What is the chemical symbol for hydrogen?", "answer": "H", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for hydrogen is ____."}, {"prompt": "What is the chemical symbol for helium?", "answer": "He", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for helium is ____."}, {"prompt": "What is the chemical symbol for lithium?", "answer": "Li", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for lithium is ____."}, {"prompt": "What is the chemical symbol for beryllium?", "answer": "Be", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for beryllium is ____."}, {"prompt": "What is the chemical symbol for boron?", "answer": "B", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for boron is ____."}, {"prompt": "What is the chemical symbol for carbon?", "answer": "C", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for carbon is ____."}]}, {"id": "atomic_matter-symbols6", "name": "Element symbols 7–12", "summary": "nitrogen = N; oxygen = O; fluorine = F; neon = Ne; sodium = Na; magnesium = Mg.", "blanks": ["N", "O", "F", "Ne", "Na", "Mg"], "questions": [{"prompt": "What is the chemical symbol for nitrogen?", "answer": "N", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for nitrogen is ____."}, {"prompt": "What is the chemical symbol for oxygen?", "answer": "O", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for oxygen is ____."}, {"prompt": "What is the chemical symbol for fluorine?", "answer": "F", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for fluorine is ____."}, {"prompt": "What is the chemical symbol for neon?", "answer": "Ne", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for neon is ____."}, {"prompt": "What is the chemical symbol for sodium?", "answer": "Na", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for sodium is ____."}, {"prompt": "What is the chemical symbol for magnesium?", "answer": "Mg", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for magnesium is ____."}]}, {"id": "atomic_matter-symbols12", "name": "Element symbols 13–18", "summary": "aluminium = Al; silicon = Si; phosphorus = P; sulfur = S; chlorine = Cl; argon = Ar.", "blanks": ["Al", "Si", "P", "S", "Cl", "Ar"], "questions": [{"prompt": "What is the chemical symbol for aluminium?", "answer": "Al", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for aluminium is ____."}, {"prompt": "What is the chemical symbol for silicon?", "answer": "Si", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for silicon is ____."}, {"prompt": "What is the chemical symbol for phosphorus?", "answer": "P", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for phosphorus is ____."}, {"prompt": "What is the chemical symbol for sulfur?", "answer": "S", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for sulfur is ____."}, {"prompt": "What is the chemical symbol for chlorine?", "answer": "Cl", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for chlorine is ____."}, {"prompt": "What is the chemical symbol for argon?", "answer": "Ar", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for argon is ____."}]}, {"id": "atomic_matter-symbols18", "name": "Element symbols 19–24", "summary": "potassium = K; calcium = Ca; iron = Fe; copper = Cu; silver = Ag; gold = Au.", "blanks": ["K", "Ca", "Fe", "Cu", "Ag", "Au"], "questions": [{"prompt": "What is the chemical symbol for potassium?", "answer": "K", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for potassium is ____."}, {"prompt": "What is the chemical symbol for calcium?", "answer": "Ca", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for calcium is ____."}, {"prompt": "What is the chemical symbol for iron?", "answer": "Fe", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for iron is ____."}, {"prompt": "What is the chemical symbol for copper?", "answer": "Cu", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for copper is ____."}, {"prompt": "What is the chemical symbol for silver?", "answer": "Ag", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for silver is ____."}, {"prompt": "What is the chemical symbol for gold?", "answer": "Au", "aliases": [], "explanation": "Chemical symbols begin with a capital letter; any second letter is lowercase.", "cloze": "The chemical symbol for gold is ____."}]}, {"id": "atomic_matter-mass", "name": "Particle masses and bonding", "summary": "Protons and neutrons each have relative mass about 1. Electrons have very small relative mass. Ionic bonding attracts opposite ions; covalent bonding shares electrons.", "blanks": ["1", "small", "opposite", "shares"], "questions": [{"prompt": "Which has much smaller relative mass: a proton or an electron?", "answer": "electron", "aliases": [], "explanation": "Electron mass is approximately 1/1836 of a proton’s.", "cloze": "Of a proton and an electron, the particle with much smaller relative mass is the ____."}, {"prompt": "Do ionic bonds attract ions of the same or opposite charge?", "answer": "opposite", "aliases": [], "explanation": "Opposite electrical charges attract.", "cloze": "Ionic bonds attract ions with ____ charges."}, {"prompt": "Do covalent bonds transfer or share electrons?", "answer": "share", "aliases": [], "explanation": "Atoms share electron pairs in covalent bonds.", "cloze": "Covalent bonds ____ electrons."}]}, {"id": "atomic_matter-group_properties", "name": "Groups and electron shells", "summary": "Atoms in a group have similar chemistry. Period number indicates occupied shells for the first 20 elements. Group 18 has full outer shells and is very unreactive.", "blanks": ["similar", "shells", "full"], "questions": [{"prompt": "A neutral atom has arrangement 2,8,1. Which period is it in?", "answer": "3", "aliases": [], "explanation": "There are three occupied shells.", "cloze": "An atom with arrangement 2,8,1 is in period ____."}, {"prompt": "Which group is very unreactive: 1, 17 or 18?", "answer": "18", "aliases": [], "explanation": "Noble gases have full outer shells.", "cloze": "The very unreactive group is group ____."}, {"prompt": "Atoms in one group generally have similar or completely different chemical properties?", "answer": "similar", "aliases": [], "explanation": "For the main groups, similar outer-shell arrangements give similar chemistry.", "cloze": "Atoms in one group generally have ____ chemical properties."}]}, {"id": "atomic_matter-shell_practice0", "name": "Electron arrangements 1–5", "summary": "For a neutral atom, electrons equal atomic number. Use the first-20 shell model; count outer electrons to find valence electrons.", "blanks": ["atomic number", "outer"], "questions": [{"prompt": "Give the electron arrangement of neutral hydrogen, atomic number 1.", "answer": "1", "aliases": [], "explanation": "1 electrons fill the school-model shells in order.", "cloze": "Neutral hydrogen, atomic number 1 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral helium, atomic number 2.", "answer": "2", "aliases": [], "explanation": "2 electrons fill the school-model shells in order.", "cloze": "Neutral helium, atomic number 2 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral lithium, atomic number 3.", "answer": "2,1", "aliases": [], "explanation": "3 electrons fill the school-model shells in order.", "cloze": "Neutral lithium, atomic number 3 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral beryllium, atomic number 4.", "answer": "2,2", "aliases": [], "explanation": "4 electrons fill the school-model shells in order.", "cloze": "Neutral beryllium, atomic number 4 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral boron, atomic number 5.", "answer": "2,3", "aliases": [], "explanation": "5 electrons fill the school-model shells in order.", "cloze": "Neutral boron, atomic number 5 has electron arrangement ____."}]}, {"id": "atomic_matter-shell_practice5", "name": "Electron arrangements 6–10", "summary": "For a neutral atom, electrons equal atomic number. Use the first-20 shell model; count outer electrons to find valence electrons.", "blanks": ["atomic number", "outer"], "questions": [{"prompt": "Give the electron arrangement of neutral carbon, atomic number 6.", "answer": "2,4", "aliases": [], "explanation": "6 electrons fill the school-model shells in order.", "cloze": "Neutral carbon, atomic number 6 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral nitrogen, atomic number 7.", "answer": "2,5", "aliases": [], "explanation": "7 electrons fill the school-model shells in order.", "cloze": "Neutral nitrogen, atomic number 7 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral oxygen, atomic number 8.", "answer": "2,6", "aliases": [], "explanation": "8 electrons fill the school-model shells in order.", "cloze": "Neutral oxygen, atomic number 8 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral fluorine, atomic number 9.", "answer": "2,7", "aliases": [], "explanation": "9 electrons fill the school-model shells in order.", "cloze": "Neutral fluorine, atomic number 9 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral neon, atomic number 10.", "answer": "2,8", "aliases": [], "explanation": "10 electrons fill the school-model shells in order.", "cloze": "Neutral neon, atomic number 10 has electron arrangement ____."}]}, {"id": "atomic_matter-shell_practice10", "name": "Electron arrangements 11–15", "summary": "For a neutral atom, electrons equal atomic number. Use the first-20 shell model; count outer electrons to find valence electrons.", "blanks": ["atomic number", "outer"], "questions": [{"prompt": "Give the electron arrangement of neutral sodium, atomic number 11.", "answer": "2,8,1", "aliases": [], "explanation": "11 electrons fill the school-model shells in order.", "cloze": "Neutral sodium, atomic number 11 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral magnesium, atomic number 12.", "answer": "2,8,2", "aliases": [], "explanation": "12 electrons fill the school-model shells in order.", "cloze": "Neutral magnesium, atomic number 12 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral aluminium, atomic number 13.", "answer": "2,8,3", "aliases": [], "explanation": "13 electrons fill the school-model shells in order.", "cloze": "Neutral aluminium, atomic number 13 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral silicon, atomic number 14.", "answer": "2,8,4", "aliases": [], "explanation": "14 electrons fill the school-model shells in order.", "cloze": "Neutral silicon, atomic number 14 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral phosphorus, atomic number 15.", "answer": "2,8,5", "aliases": [], "explanation": "15 electrons fill the school-model shells in order.", "cloze": "Neutral phosphorus, atomic number 15 has electron arrangement ____."}]}, {"id": "atomic_matter-shell_practice15", "name": "Electron arrangements 16–20", "summary": "For a neutral atom, electrons equal atomic number. Use the first-20 shell model; count outer electrons to find valence electrons.", "blanks": ["atomic number", "outer"], "questions": [{"prompt": "Give the electron arrangement of neutral sulfur, atomic number 16.", "answer": "2,8,6", "aliases": [], "explanation": "16 electrons fill the school-model shells in order.", "cloze": "Neutral sulfur, atomic number 16 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral chlorine, atomic number 17.", "answer": "2,8,7", "aliases": [], "explanation": "17 electrons fill the school-model shells in order.", "cloze": "Neutral chlorine, atomic number 17 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral argon, atomic number 18.", "answer": "2,8,8", "aliases": [], "explanation": "18 electrons fill the school-model shells in order.", "cloze": "Neutral argon, atomic number 18 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral potassium, atomic number 19.", "answer": "2,8,8,1", "aliases": [], "explanation": "19 electrons fill the school-model shells in order.", "cloze": "Neutral potassium, atomic number 19 has electron arrangement ____."}, {"prompt": "Give the electron arrangement of neutral calcium, atomic number 20.", "answer": "2,8,8,2", "aliases": [], "explanation": "20 electrons fill the school-model shells in order.", "cloze": "Neutral calcium, atomic number 20 has electron arrangement ____."}]}], "applications": [{"prompt": "Draw a labelled shell diagram of neutral magnesium with atomic number 12 and mass number 24. Then describe its common ion, including particle counts and shell arrangement.", "answer": "Neutral Mg: 12 protons, 12 neutrons, 12 electrons; shells 2,8,2. Mg2+ loses two electrons: 12 protons, 12 neutrons, 10 electrons; shells 2,8. The nucleus does not change."}, {"prompt": "Explain the difference between magnesium oxide and a mixture of magnesium and oxygen. Given Mg2+ and O2−, derive the ionic formula and explain what holds its ions together.", "answer": "A compound contains elements chemically bonded in a fixed ratio; a mixture contains substances together without that fixed chemical combination. MgO is 1:1, balancing +2 and −2. Electrostatic attraction holds opposite ions together."}, {"prompt": "An atom has arrangement 2,8,7. Identify its period, valence electrons and likely ion charge. Compare its group’s reactivity trend with group 1.", "answer": "Three occupied shells → period 3; seven valence electrons → group 17; gaining one electron forms a −1 ion. Group 17 reactivity decreases down the group; group 1 increases."}]}, {"id": "forces_motion", "name": "Forces & Motion", "source": "Y10 Forces and Motion Unit Plan 2026 .docx", "status": "ready", "skills": [{"id": "forces_motion-forces", "name": "Types of force", "summary": "A force is a push or pull measured in newtons (N). Friction opposes relative motion; support acts perpendicular to a surface; weight is gravitational force.", "blanks": ["newtons", "Friction", "weight"], "questions": [{"prompt": "Which unit measures force?", "answer": "newton", "aliases": ["newtons", "N"], "explanation": "Force is measured in newtons, not kilograms.", "cloze": "Force is measured in the unit ____."}, {"prompt": "Which force opposes sliding between surfaces?", "answer": "friction", "aliases": [], "explanation": "Friction opposes relative sliding motion.", "cloze": "The force opposing sliding between surfaces is ____."}, {"prompt": "Is gravity a contact or non-contact force?", "answer": "non-contact", "aliases": ["non contact"], "explanation": "It acts without surfaces touching.", "cloze": "Gravity is a ____ force."}]}, {"id": "forces_motion-net", "name": "Net force", "summary": "Opposing forces subtract. Balanced forces give zero net force and no change in velocity. Moving at constant velocity does not require a net force.", "blanks": ["subtract", "zero", "velocity"], "questions": [{"prompt": "10 N right and 4 N left act on a trolley. Give the net force in N to the right (number only).", "answer": "6", "aliases": [], "explanation": "10 − 4 = 6 N right.", "cloze": "A trolley has 10 N right and 4 N left: net force = ____ N right."}, {"prompt": "8 N left and 8 N right act on a trolley. Give net force in N (number only).", "answer": "0", "aliases": [], "explanation": "Equal opposing forces cancel.", "cloze": "A trolley has 8 N left and 8 N right: net force = ____ N."}, {"prompt": "A trolley moves at constant velocity. Is its net force zero or non-zero?", "answer": "zero", "aliases": ["0"], "explanation": "Constant velocity means zero acceleration and zero net force.", "cloze": "At constant velocity, a trolley’s net force is ____."}]}, {"id": "forces_motion-acceleration", "name": "Acceleration and Newton’s laws", "summary": "Acceleration is change in velocity, including slowing or changing direction. Zero net force means constant velocity. F = ma uses net force.", "blanks": ["velocity", "net"], "questions": [{"prompt": "Can changing direction at constant speed be acceleration: yes or no?", "answer": "yes", "aliases": [], "explanation": "Direction is part of velocity.", "cloze": "Changing direction at constant speed counts as acceleration: ____ (yes/no)."}, {"prompt": "Net force is 12 N and mass is 3 kg. Calculate acceleration in m/s² (number only).", "answer": "4", "aliases": [], "explanation": "a = F/m = 12/3 = 4 m/s².", "cloze": "F = 12 N, m = 3 kg: a = ____ m/s²."}, {"prompt": "A 5 kg object accelerates at 2 m/s². Calculate net force in N (number only).", "answer": "10", "aliases": [], "explanation": "F = ma = 5 × 2 = 10 N.", "cloze": "m = 5 kg, a = 2 m/s²: F = ____ N."}]}, {"id": "forces_motion-weight", "name": "Mass and weight", "summary": "Mass is measured in kg; weight is a force measured in N. W = mg. Always use the supplied g; these practice questions specify 10 N/kg.", "blanks": ["kg", "N", "W = mg"], "questions": [{"prompt": "Calculate the weight of 3 kg using g = 10 N/kg. Answer in N (number only).", "answer": "30", "aliases": [], "explanation": "W = mg = 3 × 10 = 30 N.", "cloze": "m = 3 kg, g = 10 N/kg: weight = ____ N."}, {"prompt": "Weight is 60 N where g = 10 N/kg. Calculate mass in kg (number only).", "answer": "6", "aliases": [], "explanation": "m = W/g = 60/10 = 6 kg.", "cloze": "Weight = 60 N, g = 10 N/kg: mass = ____ kg."}, {"prompt": "On the Moon, which stays the same: mass or weight?", "answer": "mass", "aliases": [], "explanation": "Mass stays the same; a different gravitational field changes weight.", "cloze": "On the Moon, the quantity that stays the same is ____."}]}, {"id": "forces_motion-speed", "name": "Speed, distance and time", "summary": "Speed v = d/t. Distance d = vt. Time t = d/v. Use matching distance and time units.", "blanks": ["d/t", "vt", "d/v"], "questions": [{"prompt": "Travel 60 m in 12 s. Calculate speed in m/s (number only).", "answer": "5", "aliases": [], "explanation": "v = 60/12 = 5 m/s.", "cloze": "d = 60 m, t = 12 s: v = ____ m/s."}, {"prompt": "Travel at 4 m/s for 15 s. Calculate distance in m (number only).", "answer": "60", "aliases": [], "explanation": "d = 4 × 15 = 60 m.", "cloze": "v = 4 m/s, t = 15 s: d = ____ m."}, {"prompt": "Travel 90 m at 6 m/s. Calculate time in s (number only).", "answer": "15", "aliases": [], "explanation": "t = 90/6 = 15 s.", "cloze": "d = 90 m, v = 6 m/s: t = ____ s."}]}, {"id": "forces_motion-units", "name": "Unit conversions", "summary": "1 km = 1000 m. 1 minute = 60 seconds. 1 hour = 3600 seconds. Convert units before substituting into a formula.", "blanks": ["1000", "60", "3600"], "questions": [{"prompt": "Convert 2.5 km to m (number only).", "answer": "2500", "aliases": [], "explanation": "Multiply kilometres by 1000.", "cloze": "2.5 km = ____ m."}, {"prompt": "Convert 3 minutes to seconds (number only).", "answer": "180", "aliases": [], "explanation": "3 × 60 = 180 s.", "cloze": "3 minutes = ____ s."}, {"prompt": "Travel 1.2 km in 2 minutes. Calculate speed in m/s (number only).", "answer": "10", "aliases": [], "explanation": "1200 m ÷ 120 s = 10 m/s.", "cloze": "d = 1.2 km, t = 2 minutes: v = ____ m/s."}]}, {"id": "forces_motion-graphs", "name": "Distance–time graphs", "summary": "Time goes on the x-axis and distance on the y-axis. Gradient is speed. A horizontal line is stationary; a straight sloping line is constant speed.", "blanks": ["x-axis", "y-axis", "speed", "stationary"], "questions": [{"prompt": "What does a distance–time graph’s gradient represent?", "answer": "speed", "aliases": [], "explanation": "Speed = change in distance ÷ change in time.", "cloze": "The gradient of a distance–time graph represents ____."}, {"prompt": "What motion does a horizontal distance–time line show?", "answer": "stationary", "aliases": ["stopped", "at rest", "not moving"], "explanation": "Distance does not change as time passes.", "cloze": "A horizontal distance–time line means the object is ____."}, {"prompt": "Distance rises from 10 m at 2 s to 30 m at 6 s. Calculate gradient in m/s (number only).", "answer": "5", "aliases": [], "explanation": "(30 − 10)/(6 − 2) = 20/4 = 5 m/s.", "cloze": "Distance rises from 10 m at 2 s to 30 m at 6 s: gradient = ____ m/s."}]}, {"id": "forces_motion-graphs2", "name": "Changing speed and graph interpretation", "summary": "On a distance–time graph, a steeper slope means faster motion. A curve becoming steeper shows increasing speed; height alone does not show speed.", "blanks": ["steeper", "increasing", "height"], "questions": [{"prompt": "A distance–time curve becomes steeper. Is speed increasing or decreasing?", "answer": "increasing", "aliases": ["increase"], "explanation": "Its gradient is getting larger.", "cloze": "A distance–time curve becomes steeper: speed is ____."}, {"prompt": "A has gradient 2 m/s; B has gradient 5 m/s. Which is faster: A or B?", "answer": "B", "aliases": [], "explanation": "The larger gradient is the larger speed.", "cloze": "A has gradient 2 m/s; B has gradient 5 m/s. The faster object is ____."}, {"prompt": "A flat graph segment is high above the axis. Is the object moving during that segment: yes or no?", "answer": "no", "aliases": [], "explanation": "Height shows distance; zero gradient shows no movement.", "cloze": "A flat distance–time segment is high above the axis. The object is moving: ____ (yes/no)."}]}, {"id": "forces_motion-stability", "name": "Centre of gravity and stability", "summary": "The centre of gravity is the point through which the resultant weight acts. A lower centre of gravity and wider base generally improve stability. An object tips when the weight’s line of action falls outside its base.", "blanks": ["weight", "lower", "wider", "outside"], "questions": [{"prompt": "Lowering the centre of gravity generally increases or decreases stability?", "answer": "increases", "aliases": ["increase"], "explanation": "It takes a larger tilt before the weight line leaves the base.", "cloze": "Lowering the centre of gravity generally ____ stability."}, {"prompt": "Widening an object’s base generally increases or decreases stability?", "answer": "increases", "aliases": ["increase"], "explanation": "A wider base allows a larger tilt before tipping.", "cloze": "Widening the base generally ____ stability."}, {"prompt": "Does an object tip when its weight’s line of action is inside or outside the base?", "answer": "outside", "aliases": [], "explanation": "The resultant weight produces a turning effect about the edge.", "cloze": "An object tips when its weight’s line of action is ____ the base."}]}], "applications": [{"prompt": "Draw a distance–time graph through (0 s,0 m), (4 s,12 m), (8 s,12 m), (12 s,36 m). Calculate speed in each section and describe the journey.", "answer": "First section: 12/4 = 3 m/s. Middle: stationary, 0 m/s. Last: (36−12)/(12−8) = 6 m/s. Label time on x, distance on y, units and suitable scales."}, {"prompt": "Draw a force diagram for a trolley travelling right at constant velocity. Then show what changes if its thrust exceeds friction by 6 N. For a mass of 3 kg, find acceleration.", "answer": "At constant velocity, thrust balances friction and support balances weight. With 6 N net right, it accelerates right: a = F/m = 6/3 = 2 m/s². Motion to the right alone does not prove a net force."}, {"prompt": "Explain why a low, wide-based object usually resists tipping better than a high, narrow-based one. Draw its centre of gravity, weight arrow and base.", "answer": "Tipping begins when the weight’s line of action falls outside the base. A lower centre of gravity and wider base usually require a larger tilt before that happens; actual stability depends on both."}]}, {"id": "electricity_magnetism", "name": "Electricity & Magnetism", "source": "Y10_Electricity_and_Magnetism_GC_Template_3Week_Core_5Week_Extension_2026.docx; existing 80-card core deck", "status": "ready", "skills": [{"id": "electricity_magnetism-charge", "name": "Charge and static electricity", "summary": "Charges are positive or negative. Like charges repel and opposite charges attract. Static charging involves transfer of electrons.", "blanks": ["repel", "attract", "electrons"], "questions": [{"prompt": "Two negatively charged objects attract or repel?", "answer": "repel", "aliases": [], "explanation": "Like charges repel.", "cloze": "Two negatively charged objects ____."}, {"prompt": "A positive and a negative charge attract or repel?", "answer": "attract", "aliases": [], "explanation": "Unlike charges attract.", "cloze": "A positive and a negative charge ____."}, {"prompt": "An object gains electrons. Does it become positive or negative?", "answer": "negative", "aliases": [], "explanation": "Added electrons give it excess negative charge.", "cloze": "An object gains electrons and becomes ____."}]}, {"id": "electricity_magnetism-paths", "name": "Circuits and materials", "summary": "Current needs a complete conducting path. Conductors allow charge to flow; insulators resist it. Series has one path; parallel has separate branches.", "blanks": ["complete", "Conductors", "one", "branches"], "questions": [{"prompt": "A switch is open. Can current flow around that circuit: yes or no?", "answer": "no", "aliases": [], "explanation": "An open switch breaks the conducting path.", "cloze": "An open switch permits current around its circuit: ____ (yes/no)."}, {"prompt": "Is copper a conductor or insulator?", "answer": "conductor", "aliases": [], "explanation": "Copper allows charge to flow easily.", "cloze": "Copper is a ____."}, {"prompt": "Which circuit has separate branches: series or parallel?", "answer": "parallel", "aliases": [], "explanation": "Parallel branches provide multiple paths.", "cloze": "A circuit with separate branches is a ____ circuit."}]}, {"id": "electricity_magnetism-meters", "name": "Quantities, units and meters", "summary": "Current I is measured in amperes A with an ammeter in series. Voltage V is measured in volts V with a voltmeter in parallel. Resistance R is measured in ohms Ω.", "blanks": ["amperes", "series", "volts", "parallel", "ohms"], "questions": [{"prompt": "Connect an ammeter in series or parallel?", "answer": "series", "aliases": [], "explanation": "It measures the current passing through it.", "cloze": "An ammeter is connected in ____."}, {"prompt": "Connect a voltmeter across a component in series or parallel?", "answer": "parallel", "aliases": [], "explanation": "It measures the potential difference between the component’s ends.", "cloze": "A voltmeter across a component is connected in ____."}, {"prompt": "What is the unit of resistance?", "answer": "ohm", "aliases": ["ohms", "Ω", "omega"], "explanation": "Resistance is measured in ohms, symbol Ω.", "cloze": "The unit of resistance is the ____."}]}, {"id": "electricity_magnetism-series", "name": "Series rules", "summary": "In series, current is the same everywhere. Voltage drops add to the supply voltage. Removing one component breaks the single path.", "blanks": ["same", "add", "breaks"], "questions": [{"prompt": "Current through lamp A is 2 A in series. Current through lamp B in A (number only)?", "answer": "2", "aliases": [], "explanation": "Series current is the same at every point.", "cloze": "In series, lamp A carries 2 A: lamp B carries ____ A."}, {"prompt": "A 9 V supply feeds two series lamps. One has 4 V. Find the other voltage in V (number only).", "answer": "5", "aliases": [], "explanation": "Voltage drops add: 9 − 4 = 5 V.", "cloze": "A 9 V supply feeds two series lamps; one has 4 V. The other has ____ V."}, {"prompt": "One lamp is removed from a series circuit. Does the other stay on: yes or no?", "answer": "no", "aliases": [], "explanation": "Removing a lamp breaks the only path.", "cloze": "Removing one series lamp leaves the other lit: ____ (yes/no)."}]}, {"id": "electricity_magnetism-parallel", "name": "Parallel rules", "summary": "Parallel branch voltages equal the supply voltage. Branch currents add to the total current. Breaking one branch leaves other complete branches working.", "blanks": ["equal", "add", "other"], "questions": [{"prompt": "A parallel circuit has a 6 V supply. What voltage is across each lamp in V (number only)?", "answer": "6", "aliases": [], "explanation": "Every branch is connected across the same supply.", "cloze": "A 6 V supply feeds parallel lamps: each lamp has ____ V."}, {"prompt": "Two parallel branches carry 2 A and 3 A. Total current in A (number only)?", "answer": "5", "aliases": [], "explanation": "Total = 2 + 3 = 5 A.", "cloze": "Parallel branches carry 2 A and 3 A: total current = ____ A."}, {"prompt": "Total current is 7 A; one branch carries 4 A. Find the other in A (number only).", "answer": "3", "aliases": [], "explanation": "Other branch = 7 − 4 = 3 A.", "cloze": "Total current = 7 A; one branch carries 4 A. The other carries ____ A."}]}, {"id": "electricity_magnetism-resistance", "name": "Resistance and energy", "summary": "Resistance opposes current. With the same supply voltage, greater resistance means less current. A lamp transfers electrical energy into light and thermal energy.", "blanks": ["less", "light", "thermal"], "questions": [{"prompt": "At the same voltage, increasing resistance gives more or less current?", "answer": "less", "aliases": [], "explanation": "Greater resistance opposes current more strongly.", "cloze": "At the same voltage, higher resistance means ____ current."}, {"prompt": "A lamp transfers electrical energy into light and which other energy form?", "answer": "thermal", "aliases": ["heat", "thermal energy", "heat energy"], "explanation": "Some energy warms the lamp and surroundings.", "cloze": "A lamp transfers electrical energy into light and ____ energy."}, {"prompt": "Is electric current used up as it passes through a lamp: yes or no?", "answer": "no", "aliases": [], "explanation": "Energy is transferred; charge continues around the circuit.", "cloze": "Current is used up as it passes through a lamp: ____ (yes/no)."}]}, {"id": "electricity_magnetism-magnets", "name": "Magnets and field lines", "summary": "Like magnetic poles repel; unlike poles attract. Field lines point north to south outside a magnet. Iron is magnetic; not all metals are magnetic.", "blanks": ["repel", "attract", "north to south", "Iron"], "questions": [{"prompt": "Two north poles attract or repel?", "answer": "repel", "aliases": [], "explanation": "Like magnetic poles repel.", "cloze": "Two north poles ____."}, {"prompt": "Outside a magnet, field lines go north-to-south or south-to-north?", "answer": "north-to-south", "aliases": ["north to south"], "explanation": "The convention is from the north pole to the south pole outside.", "cloze": "Outside a magnet, field lines go ____."}, {"prompt": "Is every metal magnetic: yes or no?", "answer": "no", "aliases": [], "explanation": "Iron is magnetic but many common metals such as copper are not.", "cloze": "Every metal is magnetic: ____ (yes/no)."}]}, {"id": "electricity_magnetism-electromagnets", "name": "Electromagnets", "summary": "A current in a coil creates a magnetic field. More turns, greater current and an iron core strengthen an electromagnet. Switching off the current removes the coil’s field.", "blanks": ["current", "turns", "iron"], "questions": [{"prompt": "Adding more turns to a coil generally makes its electromagnet stronger or weaker?", "answer": "stronger", "aliases": [], "explanation": "More turns reinforce the magnetic field for the same current.", "cloze": "More coil turns generally make an electromagnet ____."}, {"prompt": "Which core strengthens an electromagnet: iron or plastic?", "answer": "iron", "aliases": [], "explanation": "Iron is magnetic and strengthens the field.", "cloze": "The stronger electromagnet core is ____ (iron/plastic)."}, {"prompt": "Increasing coil current generally makes the electromagnet stronger or weaker?", "answer": "stronger", "aliases": [], "explanation": "Greater current produces a stronger magnetic field.", "cloze": "Greater coil current generally makes an electromagnet ____."}]}], "applications": [{"prompt": "Draw a two-lamp series circuit, adding an ammeter to measure current and a voltmeter across one lamp. If supply is 12 V and one lamp has 5 V, find the other voltage.", "answer": "Ammeter in the series path; voltmeter across the lamp, in parallel. Series voltage drops add: 12−5 = 7 V. Current is the same at each point."}, {"prompt": "Draw a two-branch parallel circuit on a 9 V supply. Branch currents are 1 A and 3 A. Label voltages and total current, then explain why removing one lamp leaves the other lit.", "answer": "Each branch has 9 V; total current is 1+3 = 4 A. Removing one lamp breaks only that branch; the other still has a complete path across the supply."}, {"prompt": "Design a fair comparison of electromagnet strength at 10 and 20 coil turns. Name the independent, dependent and two control variables. Explain the predicted result.", "answer": "Independent: turns. Dependent: a consistent strength measure, such as number of identical clips lifted. Control current, core and wire/material geometry as practical. More turns generally strengthen the field at the same current. Repeat readings and compare means."}]}, {"id": "investigation_skills", "name": "Investigation Skills — across units", "source": "Transferable skills drawn from practical activities in the existing Forces, Genetics and Electricity unit plans; no dedicated unit plan", "status": "cross-unit", "skills": [{"id": "investigation_skills-variables", "name": "Variables and fair tests", "summary": "Change the independent variable; measure the dependent variable; keep control variables the same. A fair comparison changes one relevant factor at a time.", "blanks": ["independent", "dependent", "control"], "questions": [{"prompt": "Test how coil turns affect electromagnet strength. Which is independent: turns or strength?", "answer": "turns", "aliases": ["coil turns", "number of turns"], "explanation": "You deliberately change the number of turns.", "cloze": "Testing coil turns against electromagnet strength: the independent variable is ____."}, {"prompt": "Test how surface type affects friction force. Which is dependent: surface or friction force?", "answer": "friction force", "aliases": ["friction"], "explanation": "This is the measured outcome.", "cloze": "Testing surface type against friction force: the dependent variable is ____."}, {"prompt": "When comparing different insulation jackets, keep water’s starting temperature the same or different?", "answer": "same", "aliases": ["the same"], "explanation": "Starting temperature is a control variable.", "cloze": "When comparing insulation jackets, keep water’s initial temperature the ____."}]}, {"id": "investigation_skills-evidence", "name": "Data and evidence", "summary": "Repeat measurements to assess variation. State units in table headings. Put the independent variable on the x-axis and the dependent variable on the y-axis for a relationship graph. Conclusions should use data.", "blanks": ["Repeat", "units", "x-axis", "y-axis"], "questions": [{"prompt": "Which axis usually shows the independent variable: x or y?", "answer": "x", "aliases": ["x-axis", "x axis"], "explanation": "The independent variable is usually plotted on the horizontal axis.", "cloze": "The independent variable usually goes on the ____ axis."}, {"prompt": "Friction readings are 4 N, 5 N and 6 N. Calculate the mean in N (number only).", "answer": "5", "aliases": [], "explanation": "Mean = (4 + 5 + 6)/3 = 5 N.", "cloze": "Readings 4 N, 5 N and 6 N give a mean of ____ N."}, {"prompt": "Does repeating measurements guarantee no systematic error: yes or no?", "answer": "no", "aliases": [], "explanation": "Repeats show random variation but do not remove a consistently miscalibrated instrument.", "cloze": "Repeating measurements guarantees no systematic error: ____ (yes/no)."}]}], "applications": [{"prompt": "Design a test of how surface type affects friction. Name the independent and dependent variables, two controls, the units and how you would repeat the measurements.", "answer": "Independent: surface type. Dependent: friction force in N. Controls: object/mass and a consistent pulling method. Repeat each surface several times with the same equipment; compare means and variation."}, {"prompt": "Readings are 5, 6, 5 and 20 N. What should you do before discarding 20 N? Explain why more repeats do not fix a zero error in the force meter.", "answer": "Check the procedure, record the reading and repeat to investigate an anomaly rather than deleting it automatically. A zero error biases readings consistently; repeating the same faulty method does not remove it."}, {"prompt": "An insulation test compares equal starting temperatures and different jackets. Draw a suitable results-table heading and explain how measured data supports a conclusion.", "answer": "Table headings include jacket/material, elapsed time (min) and temperature (°C), with repeat identifiers. Compare temperature drop over the same time interval; use actual values and variation to justify which reduced heat loss."}]}, {"id": "genetics", "name": "Genetics & Inheritance", "source": "Junior Science Unit Plan Y10 Genetics - updated.docx; Year_10_Genetics_Assessment_Schedule_V4.pdf", "status": "ready", "skills": [{"id": "genetics-traits", "name": "Traits, heredity and phenotype", "summary": "Traits are characteristics. Heredity passes genetic information from parents to offspring. Phenotype is observable characteristics, influenced by genes and environment.", "blanks": ["Heredity", "Phenotype", "environment"], "questions": [{"prompt": "What term means observable characteristics of an organism?", "answer": "phenotype", "aliases": [], "explanation": "Phenotype includes features such as appearance and measurable traits.", "cloze": "An organism’s observable characteristics are its ____."}, {"prompt": "What term means passing genetic information from parents to offspring?", "answer": "heredity", "aliases": ["inheritance"], "explanation": "Offspring inherit genetic information from their parents.", "cloze": "Passing genetic information from parents to offspring is ____."}, {"prompt": "Is a scar mainly an inherited or environmental characteristic?", "answer": "environmental", "aliases": [], "explanation": "A scar results from an injury rather than inherited genetic information.", "cloze": "A scar is mainly an ____ characteristic."}]}, {"id": "genetics-variation", "name": "Variation and environment", "summary": "Variation means differences within a species. Continuous variation has a range of values; discontinuous variation has distinct categories. Both genes and environment can affect height.", "blanks": ["within", "range", "categories", "Both"], "questions": [{"prompt": "Is height continuous or discontinuous variation?", "answer": "continuous", "aliases": [], "explanation": "Height can take a range of measured values.", "cloze": "Height is ____ variation."}, {"prompt": "Is ABO blood group continuous or discontinuous variation?", "answer": "discontinuous", "aliases": [], "explanation": "The blood groups form distinct categories.", "cloze": "ABO blood group is ____ variation."}, {"prompt": "Is height influenced by genes, environment or both?", "answer": "both", "aliases": [], "explanation": "Inherited information and environmental factors such as nutrition affect height.", "cloze": "Height is influenced by ____ (genes/environment/both)."}]}, {"id": "genetics-dna", "name": "DNA, genes and chromosomes", "summary": "DNA carries genetic information and is packaged into chromosomes. A gene is a section of DNA. In animal and plant cells, most DNA is in the nucleus.", "blanks": ["chromosomes", "section", "nucleus"], "questions": [{"prompt": "A gene is a section of which molecule?", "answer": "DNA", "aliases": [], "explanation": "Genes are sections of DNA containing genetic instructions.", "cloze": "A gene is a section of ____."}, {"prompt": "What structures package DNA in a nucleus?", "answer": "chromosomes", "aliases": ["chromosome"], "explanation": "A chromosome contains a long DNA molecule with many genes.", "cloze": "DNA in a nucleus is packaged into ____."}, {"prompt": "Where is most DNA found in an animal cell?", "answer": "nucleus", "aliases": ["the nucleus"], "explanation": "Most DNA is in the nucleus; a small amount is in mitochondria.", "cloze": "Most DNA in an animal cell is in the ____."}]}, {"id": "genetics-bases", "name": "DNA structure and bases", "summary": "DNA is a double helix. A pairs with T; C pairs with G. DNA instructions influence proteins, which help produce traits.", "blanks": ["double helix", "T", "G", "proteins"], "questions": [{"prompt": "Which DNA base pairs with A? Give its letter.", "answer": "T", "aliases": [], "explanation": "A pairs with T (adenine with thymine).", "cloze": "In DNA, A pairs with ____."}, {"prompt": "Which DNA base pairs with C? Give its letter.", "answer": "G", "aliases": [], "explanation": "C pairs with G (cytosine with guanine).", "cloze": "In DNA, C pairs with ____."}, {"prompt": "What is the name of DNA’s twisted-ladder shape?", "answer": "double helix", "aliases": [], "explanation": "DNA has two strands twisted into a double helix.", "cloze": "DNA’s twisted-ladder shape is called a ____."}]}, {"id": "genetics-alleles", "name": "Alleles and genotype", "summary": "Alleles are different versions of a gene. Genotype is the allele combination. Homozygous means two identical alleles; heterozygous means two different alleles.", "blanks": ["versions", "Genotype", "identical", "different"], "questions": [{"prompt": "What term means a different version of a gene?", "answer": "allele", "aliases": ["an allele"], "explanation": "Alleles are alternative versions of one gene.", "cloze": "A different version of a gene is an ____."}, {"prompt": "Is Bb homozygous or heterozygous?", "answer": "heterozygous", "aliases": [], "explanation": "B and b are different alleles.", "cloze": "The genotype Bb is ____."}, {"prompt": "Is bb homozygous or heterozygous?", "answer": "homozygous", "aliases": ["homozygous recessive"], "explanation": "The two alleles are identical.", "cloze": "The genotype bb is ____."}]}, {"id": "genetics-dominance", "name": "Dominant and recessive inheritance", "summary": "In a simple dominant/recessive model, a dominant allele affects phenotype in a heterozygote. A recessive phenotype needs two recessive alleles. Dominant does not mean common, stronger or better.", "blanks": ["heterozygote", "two", "common"], "questions": [{"prompt": "B gives black fur and is dominant to b. Is Bb black or white?", "answer": "black", "aliases": [], "explanation": "One dominant B allele produces black fur in this model.", "cloze": "B gives dominant black fur; b gives white fur. Bb has ____ fur."}, {"prompt": "B gives black fur; b gives recessive white fur. Give the white genotype.", "answer": "bb", "aliases": [], "explanation": "The recessive phenotype requires two b alleles.", "cloze": "B gives dominant black fur; b gives white fur. White fur has genotype ____."}, {"prompt": "Does dominant automatically mean more common in the population: yes or no?", "answer": "no", "aliases": [], "explanation": "Dominance describes heterozygote expression, not frequency.", "cloze": "Dominant automatically means more common in the population: ____ (yes/no)."}]}, {"id": "genetics-cross", "name": "Punnett squares and probability", "summary": "Each offspring receives one allele from each parent. Bb × Bb gives BB, Bb, Bb, bb: 1:2:1 genotype ratio and 3:1 phenotype ratio under complete dominance. Probability is not a guarantee.", "blanks": ["one", "1:2:1", "3:1", "not"], "questions": [{"prompt": "For Bb × Bb, what percentage of offspring are predicted to be bb? Number only.", "answer": "25", "aliases": [], "explanation": "One of four equally likely combinations is bb.", "cloze": "Bb × Bb predicts ____% bb offspring."}, {"prompt": "For Bb × bb, what percentage are predicted to be bb? Number only.", "answer": "50", "aliases": [], "explanation": "Two of four combinations are bb; the others are Bb.", "cloze": "Bb × bb predicts ____% bb offspring."}, {"prompt": "Does a 25% probability guarantee exactly one white offspring in four births: yes or no?", "answer": "no", "aliases": [], "explanation": "Each birth is an independent chance; small families may differ from expected ratios.", "cloze": "A 25% probability guarantees exactly one white offspring in four births: ____ (yes/no)."}]}, {"id": "genetics-pure", "name": "Pure breeding and inference", "summary": "Pure breeding for a simple trait means homozygous. BB × bb gives all Bb. A dominant-phenotype parent producing recessive offspring must carry the recessive allele.", "blanks": ["homozygous", "Bb", "recessive"], "questions": [{"prompt": "Which is pure breeding: BB or Bb?", "answer": "BB", "aliases": [], "explanation": "Pure breeding means homozygous for this trait.", "cloze": "Of BB and Bb, the pure-breeding genotype is ____."}, {"prompt": "For BB × bb, give the offspring genotype.", "answer": "Bb", "aliases": ["bB"], "explanation": "Every offspring inherits B from one parent and b from the other.", "cloze": "BB × bb produces offspring with genotype ____."}, {"prompt": "A black parent crossed with bb produces white offspring. B is dominant. Give the black parent’s genotype.", "answer": "Bb", "aliases": ["bB"], "explanation": "The black parent must pass on b and must also carry B to be black.", "cloze": "A black parent crossed with bb produces white offspring. B is dominant; the black parent’s genotype is ____."}]}, {"id": "genetics-sex", "name": "XX / XY model", "summary": "In the simplified XX/XY inheritance model, eggs carry X and sperm carry X or Y. XX × XY predicts approximately equal XX and XY outcomes; probabilities do not determine gender identity.", "blanks": ["X", "X or Y", "equal"], "questions": [{"prompt": "In an XX × XY model, does an egg carry X or Y?", "answer": "X", "aliases": [], "explanation": "An XX parent supplies X in each egg in this model.", "cloze": "In the XX × XY model, an egg carries ____."}, {"prompt": "In the simplified XX × XY model, what percentage of offspring are predicted XY? Number only.", "answer": "50", "aliases": [], "explanation": "Half the equally likely chromosome combinations are XY.", "cloze": "In the XX × XY model, ____% of offspring are predicted XY."}, {"prompt": "Which supplies the variable X or Y chromosome in this model: egg or sperm?", "answer": "sperm", "aliases": [], "explanation": "Sperm can carry X or Y. This model has biological exceptions.", "cloze": "The cell supplying the variable X or Y chromosome is the ____."}]}, {"id": "genetics-mutation", "name": "Mutation and inheritance", "summary": "A mutation is a change in DNA. It may be harmful, beneficial or neutral. Mutations in gametes can be inherited; body-cell mutations generally are not passed to offspring.", "blanks": ["DNA", "neutral", "gametes"], "questions": [{"prompt": "What term means a change in DNA?", "answer": "mutation", "aliases": ["a mutation"], "explanation": "Mutations alter DNA and can produce new alleles.", "cloze": "A change in DNA is a ____."}, {"prompt": "Are mutations always harmful: yes or no?", "answer": "no", "aliases": [], "explanation": "Effects can be harmful, beneficial or neutral depending on the context.", "cloze": "Mutations are always harmful: ____ (yes/no)."}, {"prompt": "Which mutation can be inherited: one in a skin cell or one in a gamete?", "answer": "gamete", "aliases": ["one in a gamete", "gamete mutation"], "explanation": "A gamete’s DNA can be passed to offspring.", "cloze": "Of a skin cell and a gamete, an inheritable mutation is in a ____."}]}, {"id": "genetics-selection", "name": "Natural selection", "summary": "Heritable variation affects survival and reproduction under a selection pressure. Better-suited individuals leave more offspring; favourable inherited traits can become more common over generations. Individuals do not choose to evolve.", "blanks": ["Heritable", "reproduction", "generations"], "questions": [{"prompt": "Natural selection depends on survival and what other process?", "answer": "reproduction", "aliases": [], "explanation": "Traits must be passed to offspring for population change.", "cloze": "Natural selection depends on survival and ____."}, {"prompt": "Does natural selection change a population over generations or instantly change every individual?", "answer": "over generations", "aliases": ["population over generations"], "explanation": "Individuals differ; inherited traits become more common through differential reproduction.", "cloze": "Natural selection changes a population ____."}, {"prompt": "Some birds inherit disease resistance and survive an outbreak. What must they do for resistance to become more common?", "answer": "reproduce", "aliases": ["reproduce and pass it on", "have offspring"], "explanation": "Survivors must reproduce and pass the resistance alleles to offspring.", "cloze": "Inherited disease resistance can become more common if surviving birds ____."}]}, {"id": "genetics-breeding", "name": "Selective breeding", "summary": "Selective breeding means humans choose parents with desired inherited traits. Natural selection depends on environmental pressures. Repeated breeding from a small pool can reduce genetic diversity.", "blanks": ["humans", "environmental", "diversity"], "questions": [{"prompt": "A farmer chooses high-yield cattle as parents. Is this natural selection or selective breeding?", "answer": "selective breeding", "aliases": ["artificial selection"], "explanation": "Humans choose the breeding parents.", "cloze": "A farmer choosing high-yield cattle as parents is practising ____."}, {"prompt": "A disease favours inherited resistance in wild birds. Is this natural selection or selective breeding?", "answer": "natural selection", "aliases": [], "explanation": "The environment favours resistance rather than humans choosing parents.", "cloze": "A disease favouring inherited resistance in wild birds causes ____."}, {"prompt": "Breeding repeatedly from a small related group may reduce what: genetic diversity or gravity?", "answer": "genetic diversity", "aliases": [], "explanation": "A smaller allele pool can leave a population vulnerable to disease.", "cloze": "Repeated breeding from a small related group may reduce ____."}]}], "applications": [{"prompt": "In a model plant, T is dominant tall and t is recessive short. Draw Tt × tt, show all offspring genotypes and probabilities, and explain why four offspring might not split exactly 2:2.", "answer": "Gametes: T or t from Tt, t from tt. Boxes Tt,Tt,tt,tt: 50% tall, 50% short. These are probabilities for each independent fertilisation, not guaranteed counts in a small sample."}, {"prompt": "A bird population has inherited differences in disease resistance. Explain how resistance could become more common over several generations. Include variation, survival, reproduction and inheritance.", "answer": "Some birds carry resistance alleles. Disease is a selection pressure: resistant birds are more likely to survive and reproduce. Their offspring can inherit the alleles, so resistance becomes more common over generations. Birds do not choose to mutate in order to survive."}, {"prompt": "Compare natural selection and selective breeding in a farming context. Explain one risk of breeding repeatedly from a small group of related animals.", "answer": "Natural selection favours traits through environmental survival and reproduction. Selective breeding occurs when humans choose parents with desired inherited traits. A narrow related breeding pool can reduce genetic diversity and increase inherited health risks."}]}, {"id": "survival_auckland", "name": "Survival in Auckland", "source": "Earthquakes survival in Auckland ideas 2025.docx; Year 10 Earth Science End of Topic Task_Assessment.docx; GeoNet and Get Ready", "status": "unconfirmed", "skills": [{"id": "survival_auckland-plates", "name": "Plate boundaries and earthquakes", "summary": "New Zealand straddles the Pacific and Australian plates. Sudden slip on faults releases energy as earthquake waves. Not all earthquakes produce tsunamis.", "blanks": ["Pacific", "Australian", "faults"], "questions": [{"prompt": "New Zealand lies at a boundary involving the Pacific Plate and which other plate?", "answer": "Australian", "aliases": ["Australian Plate"], "explanation": "These are the two main plates at New Zealand’s boundary.", "cloze": "New Zealand lies at a boundary between the Pacific Plate and the ____ Plate."}, {"prompt": "Sudden slip along a fault releases energy. Does this describe an earthquake or neutralisation?", "answer": "earthquake", "aliases": [], "explanation": "Stored elastic energy is released as seismic waves.", "cloze": "Sudden fault slip releasing energy describes an ____."}, {"prompt": "Does every earthquake produce a tsunami: yes or no?", "answer": "no", "aliases": [], "explanation": "Tsunamis require substantial displacement of water, such as suitable movement of the sea floor.", "cloze": "Every earthquake produces a tsunami: ____ (yes/no)."}]}, {"id": "survival_auckland-monitoring", "name": "Monitoring and uncertainty", "summary": "Seismometers record ground shaking. Volcano monitoring includes seismic activity, ground deformation and gas chemistry. Monitoring is evidence, not a guarantee of the exact time of an event.", "blanks": ["ground shaking", "deformation", "not a guarantee"], "questions": [{"prompt": "What instrument records ground shaking?", "answer": "seismometer", "aliases": ["seismograph"], "explanation": "Seismic instruments detect ground motion.", "cloze": "Ground shaking is recorded by a ____."}, {"prompt": "Can scientists reliably predict an earthquake’s exact time, location and magnitude: yes or no?", "answer": "no", "aliases": [], "explanation": "Forecasts describe probabilities; they do not give reliable exact predictions.", "cloze": "Scientists can reliably predict exact earthquake time, location and magnitude: ____ (yes/no)."}, {"prompt": "Changes in volcanic gases and ground deformation are evidence for monitoring volcanoes or measuring blood group?", "answer": "monitoring volcanoes", "aliases": ["volcanoes"], "explanation": "Multiple observations help assess volcanic activity; one sign does not guarantee an eruption.", "cloze": "Volcanic gases and ground deformation provide evidence for ____."}]}, {"id": "survival_auckland-response", "name": "Earthquake and tsunami response", "summary": "During earthquake shaking: Drop, Cover and Hold. Near the coast, after long or strong shaking, move to high ground or inland when shaking stops. Follow official Civil Defence advice.", "blanks": ["Drop", "Cover", "Hold", "high ground"], "questions": [{"prompt": "During shaking: Drop, Cover and what?", "answer": "Hold", "aliases": ["hold"], "explanation": "Hold onto your shelter while protecting your head and neck.", "cloze": "During shaking: Drop, Cover and ____."}, {"prompt": "Near the coast after long or strong shaking, should you wait for an official tsunami warning: yes or no?", "answer": "no", "aliases": [], "explanation": "Move immediately to high ground or inland after shaking stops.", "cloze": "After long or strong coastal shaking, wait for an official tsunami warning: ____ (yes/no)."}, {"prompt": "For tsunami evacuation, move towards the beach or high ground?", "answer": "high ground", "aliases": ["inland", "high ground or inland"], "explanation": "Get away from coastal inundation areas.", "cloze": "For tsunami evacuation, move to ____."}]}, {"id": "survival_auckland-survival", "name": "Survival science and equipment", "summary": "Water supports hydration, food supplies energy, clothing reduces heat loss and hygiene reduces infection risk. Match each emergency item to a need and explain the consequence of missing it.", "blanks": ["hydration", "energy", "heat loss", "infection"], "questions": [{"prompt": "Food supplies the body with water only or energy?", "answer": "energy", "aliases": [], "explanation": "Food supplies chemical energy and nutrients.", "cloze": "Food supplies the body with ____."}, {"prompt": "Insulating clothing mainly reduces heat loss or generates electricity?", "answer": "heat loss", "aliases": ["reduces heat loss"], "explanation": "Insulation reduces heat transfer; it does not create heat.", "cloze": "Insulating clothing mainly reduces ____."}, {"prompt": "Does filtering visibly dirty water alone prove it is safe to drink: yes or no?", "answer": "no", "aliases": [], "explanation": "Filtration may not remove pathogens or dissolved contaminants; follow official water guidance.", "cloze": "Filtering visibly dirty water alone proves it safe to drink: ____ (yes/no)."}]}], "applications": [{"prompt": "Choose an earthquake, tsunami or volcanic hazard and explain its physical cause. Distinguish evidence used for monitoring from reliable prediction of an exact event time.", "answer": "Earthquake: sudden fault slip releases seismic energy. Tsunami: rapid displacement of a large amount of water. Volcano: magma reaches the surface. Monitoring detects seismic activity, gas or deformation and supports assessment; reliable exact earthquake prediction is not available."}, {"prompt": "Create a six-item emergency-kit plan. For each item connect its use to hydration, energy, warmth, hygiene, first aid or information, and explain the consequence of missing it.", "answer": "Possible items: water, ready-to-eat food, warm clothing, hygiene supplies, first-aid items and a radio/torch. Credit clear science reasoning and practical trade-offs. Use official Civil Defence guidance for an actual kit; this is not an exhaustive packing list."}, {"prompt": "Design a classroom model comparing two insulation materials around equal beakers of warm water. State the variables and describe how a result connects to reducing heat loss.", "answer": "Change insulation material; measure temperature drop over equal time. Control water volume, initial temperature and container. Repeat and compare means. Less cooling indicates reduced heat transfer; insulation does not produce heat."}]}];
